def plain(t):
    for a, b in PLAIN:
        t = t.replace(a, b)
    return t

def prow(lbl, e):
    return [lbl.replace('30-39', '30–39').replace('40-59', '40–59').replace('60-79', '60–79'), str(e['n']), str(e.get('events', '—')), cip(e), f"{P(e['wilson'][0])}–{P(e['wilson'][1])}%" if 'wilson' in e else '—', f"{e['deff']:.2f}" if 'deff' in e else '—', e.get('method', '').replace('CR1 logit-t, deff floored at 1', 'CR1 logit-t').replace('Korn-Graubard (CR1 deff)', 'Korn–Graubard')]
PH_ = ['Estimate', 'n', 'Events', 'Estimate (95% CI)', 'Wilson 95% CI', 'Design effect (unfloored)', 'Interval']
PW = [2.2, 0.45, 0.5, 1.45, 0.9, 0.55, 0.75]

def drow(lbl, e, extra=''):
    return [lbl, str(e['n']), '—', f"{S(100 * e['estimate'])} ({rng(e['lower'], e['upper'])}){extra}", '—', '—', 'CR1 Wald']

def methods():
    b = []
    p = lambda s: b.append(('p', s))
    h2 = lambda s: b.append(('h2', s))
    b.append(('h1', 'Supplementary Methods: Study 1 (NHANES III)'))
    h2('Data files and linkage')
    p('We used the NHANES III adult household interview, examination and laboratory files, the second-examination examination and laboratory files (fixed-width .dat files with the NCHS SAS layouts) and the prescription medication file for statin and antianginal use.[[nhanes3_files,nhanes3_secondexam]] Every column position was taken from the SAS INPUT statements and checked against the codebooks; a second, independently written reader reproduced all analysis variables before any risk was computed. A MEC second examination was identified by a non-blank physician examiner code in the second-examination file; home second examinations were excluded because the physician examination, including blood pressure, was performed only in the MEC.')
    h2('Input definitions')
    p('SBP was the mean of the second and third physician readings at each visit; the composite blood pressure variables were not used. Total and HDL cholesterol were taken in mg/dL. Serum creatinine was calibrated at both visits as 0.960 × raw − 0.184 mg/dL;[[selvin2007]] applying the calibration at the second visit is an assumption (sensitivity analysis SA4 used raw values, or raw values minus 0.23 mg/dL, the difference from the MDRD Study laboratory reported by Coresh and colleagues[[coresh2002]]). eGFR used the race-free 2021 CKD-EPI creatinine equation,[[inker2021]] unrounded, with first-visit age at both visits. Diabetes followed the rule in the main text. UACR was 100 × urine albumin/urine creatinine; albumin below detection was kept at its coded value (0.4 mg/L) and urine creatinine below detection (7.9 mg/dL) was treated as missing (SA14). Smoking, antihypertensive treatment and history came from the household interview; statin use was defined from prescription codes for statins.')
    p('Inputs outside the PREVENT domain were set to the nearest bound at each visit and in every hybrid: SBP 90–200 mm Hg, total cholesterol 130–320 mg/dL and HDL cholesterol 20–100 mg/dL (the derivation ranges[[khan2024]]), and eGFR 15–140 mL/min/1.73 m² and UACR 0.1–25,000 mg/g (the ranges of the AHA PREVENT calculator and preventr[[aha_calc,preventr]]). Under the primary bounds, 49 of 759 participants had at least one clamped value (36 at visit 1, 33 at visit 2); person-visits clamped at visits 1 and 2 were total cholesterol 20/18, HDL cholesterol 7/8, SBP 7/6 and eGFR 2/1. No UACR value was outside 0.1–25,000 mg/g.')
    h2('Outcomes')
    p('Besides the primary and key secondary outcomes defined in the main text, the prespecified outcomes were transitions and threshold crossings; continuous agreement, including the intraclass correlation coefficient (ICC), Bland–Altman limits[[bland1986]] and the reference change value (RCV) of predicted risk;[[fraser1989]] input-level repeatability; a blood pressure measurement ladder; systematic visit effects; crossing of the 7.5% PREVENT-CVD threshold; a PCE comparison; simulation benchmarks; conditional and subgroup rates; and an exploratory, assumption-heavy transport to the NHANES 2009–2010 cohort of Study 2 (Supplementary Table S14 only).')
    h2('Equations and verification')
    a = P4['a_b_vectorized_vs_pyprevent_max_pp']
    s = P7['scalar_vs_vectorized_max_pp']
    p(f"PREVENT risks were computed with a vectorized implementation of the preventr base and UACR 10-year coefficient tables[[preventr]] and checked against the pinned pyprevent package.[[pyprevent]] On synthetic profiles before scoring (P4), the maximum absolute difference was {a['base_ascvd']:.1e} pp for base ASCVD, {a['uacr_ascvd']:.1e} pp for UACR-model ASCVD and {a['base_total_cvd']:.1e} pp for total CVD, the last because pyprevent truncates one coefficient (0.360078 vs 0.3600781). Across every participant and every hybrid at scoring (P7), it was {s['base_hybrids']:.1e} pp (base) and {s['uacr_hybrids']:.1e} pp (UACR), and {s['total_cvd']:.1e} pp for total CVD at the two visits; the full-precision table was used for total CVD, and the 7.5% crossing indicator was identical under both implementations (Supplementary Table S3). A guarded wrapper refused missing UACR, non-integer or out-of-range age, non-binary indicators and out-of-domain inputs. The PCE used the coefficients and baseline survival of Goff and colleagues,[[goff2014]] with the African American equations for non-Hispanic Black participants and the White equations otherwise; two independent transcriptions were identical and the published worked examples were reproduced.")
    h2('Pipeline checks before scoring')
    p(f"Stage 1 (no risk computed) re-hashed all data files, verified the variable map, re-read every analysis variable with an independent reader, reproduced the frozen eligibility counts and audited input-level within-person variation against Lacher and colleagues and Selvin and colleagues.[[lacher2005,selvin2013]] The audit was triggered for HbA1c (net-of-analytical CV 3.41% with the laboratory-manual analytical CV, ratio 2.27 to Lacher's 1.5%) and resolved without a parsing or unit error: with Lacher's own method CV the ratio was 1.41 (Supplementary Table S3). Stage 2 computed the PCE only in a reconstruction of the cohort of Ye and colleagues (910 participants versus their 808), as a gross-error screen with four binding criteria and lenient two-sample tolerances because the cohorts overlap (Supplementary Table S2).[[ye2014]] PREVENT was computed only after both stages passed. After scoring, a separate program using only the Python standard library recomputed every risk, θ, transitions, single-swap, hold-one-fixed and Shapley results, the total CVD and PCE crossings and the cluster-robust variance from the exported participant file; all agreed (maximum risk difference {P8['risk_max_abs_diff_pp']['base']:.1e} pp for ASCVD and {P8['risk_max_abs_diff_pp']['total_cvd']:.1e} pp for total CVD).")
    h2('Attribution')
    p("For K input groups (4 in the base model, 5 in the UACR model) we scored all 2^K hybrids per participant. With D_i(S) the indicator that the category with groups S at visit-2 values differs from the all-visit-1 category (visit 1 as reference), the Shapley contribution of group k is the weighted average of D_i(S ∪ {k}) − D_i(S) over subsets S without k, with weights |S|!(K − |S| − 1)!/K!.[[shapley1953]] The same was computed with visit 2 as the reference and the two were averaged. By construction the contributions sum to each participant's change indicator, so their means sum to θ; negative contributions, where one input offsets another's crossing, were retained. On the linear predictor (LP) scale, each group's term f_k is exactly additive; we report the mean signed term, the mean absolute term, the share s_k = E[f_k·ΔLP]/E[ΔLP²] (which sums to 1), the centred share Cov(f_k, ΔLP)/Var(ΔLP) and the correlations between group terms (Supplementary Table S4). The proportion changing under every subset of remeasured groups is given in Supplementary Table S5.")
    h2('Threshold-distance curves and standardization')
    p(f"Restricted cubic splines used three knots at the 10th, 50th and 90th percentiles of distance (base π_clin: {', '.join((F(k, 3) for k in R3['K3_base']['clin']['knots']))} logit units), fixed across bootstrap replicates; the nearest-threshold indicator was retained because there were at least 40 changes. Distances are also expressed in SDs of the change in the linear predictor (base {R3['S6_base']['sd_dLP']:.3f}; UACR {R3['S6_uacr']['sd_dLP']:.3f} logit units). Instability zones were truncated at the logit midpoints between adjacent thresholds ({F(B35, 2)}% between 3% and 5%; {F(B510, 2)}% between 5% and 10%), where the nearest threshold changes. The standardization target was the 9,478 MEC-examined NHANES III adults meeting the same first-visit eligibility with complete first-visit base inputs (8,173 without a second examination, 427 with a home and 878 with a MEC second examination; 9,316 with UACR), weighted by the MEC examination weight. Their first-visit diabetes used first-visit data only; for the analysed participants this rule agreed with the protocol rule in every case. Because the target includes the analysed participants, the joint bootstrap (cluster bootstrap of the sample, Rao–Wu rescaling bootstrap of the target[[raowu1988]]; 2,000 replicates) is approximate.")
    h2('Simulation benchmarks (model-based)')
    p("Pseudo-visits were centred on each participant's visit mean (arithmetic for SBP and HbA1c, geometric for log-scale analytes) with 1,000 replicates per participant (seed 20261009). Model A gave each input independent errors with SD equal to SD(Δ)/√2 on its analysis scale, without correlation between inputs. Model B applied log-normal analytical error with SD √ln(1 + CVa²) to total and HDL cholesterol, raw creatinine and HbA1c, held SBP fixed and rounded results to the reporting resolution of the files (1 mg/dL for lipids, 0.1 mg/dL for creatinine, 0.1% for HbA1c). Analytical CV brackets were the minimum and maximum of the method CVs reported by Lacher and colleagues[[lacher2005]] and the NHANES III laboratory quality-control tables:[[labman]] total cholesterol 1.25–2.3%, HDL cholesterol 2.49–2.5%, creatinine 1.0–2.7% and HbA1c 1.57–3.1%; urine creatinine 2.2% (Lacher only) was used for the net-of-analytical CV in Supplementary Table S10. No analytical CV for urine albumin was frozen before scoring (Selvin and colleagues report quality-control inter-assay CVs of 4.8–16.1%[[selvin2013]]), so model B was not run for the UACR model. Diabetes was recomputed from simulated HbA1c in participants without self-reported or treated diabetes, and clamping was applied after simulation. The simulation error SDs were estimated once from the full sample rather than within each bootstrap replicate (a departure from the protocol; Supplementary Table S1), so the simulation intervals understate uncertainty.")
    h2('Uncertainty')
    p(f"The cluster unit was the masked pseudo-primary sampling unit (98 in the analysis set, 97 in the UACR set), used only as a cluster identifier. The CR1 variance of a mean is [G/(G − 1)]·Σ_g(Σ_{{i∈g}}(y_i − θ))²/n², floored at the binomial variance;[[cameron2015]] intervals were formed on the logit scale with t(G − 1). With fewer than 10 events, Korn–Graubard intervals were used.[[korn1998]] Paired differences of per-person values in [−1, 1] used the same variance with a Wald t interval; when there were fewer than 20 discordant pairs, a Tango score interval[[tango1998]] was required and the wider interval governed wording. This applied only to the PCE 7.5% crossing contrast ({tg['discordant']} discordant pairs); its Tango interval was computed post hoc after correcting the variance term of the helper function (Supplementary Tables S1 and S12). Bootstrap intervals used 4,000 unstratified cluster replicates in four batches. The protocol required the number of replicates to rise to 10,000 if the batch-means Monte Carlo SE of any primary-figure interval endpoint exceeded 0.1 pp; this check was implemented only for the Shapley contributions (maximum {max((max(v) for K in ('K2_base', 'K2_uacr') for v in R3[K]['batch_mcse_pp'].values())):.3f} pp) and not for other bootstrap intervals (Supplementary Table S1). Subgroup proportions were flagged if they failed NCHS presentation standards for proportions (n < 30 or Korn–Graubard width criteria).")
    h2('Sensitivity analyses')
    p('SA1 handled the domain by excluding participants with any out-of-domain input (a), clamping SBP at 90–180 mm Hg, the bound used by preventr[[preventr]] (b), keeping participants in domain at the first visit and clamping second-visit values (c) or excluding anyone outside SBP 90–180 mm Hg (the bound used in the Study 2 pilot), total cholesterol 130–320 mg/dL, HDL cholesterol 20–100 mg/dL or eGFR 15–140 mL/min/1.73 m² at either visit (d; the final Study 2 domain, SBP 90–200 mm Hg, corresponds to SA1a). SA2 used a single physician reading (the second) at each visit (a), the mean of all available readings (b), or excluded pairs measured on different arms (c). SA3 held confirmed diabetes fixed across visits (a), excluded pairs whose HbA1c method changed between visits (b), or used the count-gate diabetes rule (c). SA4 used raw (a) or Coresh-corrected (b) creatinine. SA5 excluded participants with a first-visit physician referral at level I or II or unknown level, who might have started treatment between visits. SA6 and SA7 used visit-specific age and smoking, adding each as a Shapley player. SA8 excluded pairs with implausible input changes. SA9 excluded participants with Rose exertional chest pain, antianginal prescriptions or unknown pregnancy status. SA10 reweighted the 759 to the 979 eligible participants by inverse probability of a complete pair, modelled on age (spline), sex, race and ethnicity, survey phase, smoking, antihypertensive treatment and self-reported diabetes (all complete for the 979; first-visit SBP and risk were not prespecified covariates). SA11 replaced statin use with a lipid-lowering proxy. SA12 kept participants examined by the same physician at both visits. SA13 rounded risk to 0.1 pp before categorization. SA14 excluded pairs with albumin below detection (a) or kept urine creatinine below detection (b). SA15 compared interval methods. Key sensitivity analyses (SA1a, SA2a, SA3a, SA4a, SA5, SA10) that moved θ by at least 1.5 pp were to be reported in the abstract.')
    h2('Post hoc analyses')
    p('Analyses added after results were seen are labelled post hoc (on 2026-10-09 and 2026-10-10). Supplementary Table S16 reports (1) a decomposition of SA4a, to explain why uncalibrated creatinine raised θ; (2) creatinine within-person variation on the uncalibrated scale, to compare like with like against Lacher and colleagues; (3) the Tango interval for the PCE 7.5% crossing contrast, which the protocol required but the frozen run did not compute; and (4) the SD of the change in the linear predictor by subgroup, as a partial check of the standardization assumption. A fifth item, first-visit PREVENT risk for eligible participants without complete pairs, is reported in main Table 1 to compare risk distributions. A sixth, main Table 3 and its interactive supplementary HTML page, evaluates the prespecified π_clin models on a fine grid of first-visit risks with the same 4,000 bootstrap replicates, rebuilt from the frozen participant export and seed; the rebuilt coefficients, curve values and intervals reproduce the frozen results (maximum difference 4 × 10⁻¹⁶). Added on 2026-10-10: a model-based extension of simulation model A to repeat-measurement strategies (Supplementary Figure S2 and Supplementary Table S27), to estimate how much averaging or targeted repetition would reduce instability; and a curve for crossing the 7.5% PREVENT-CVD threshold with the π_clin specification (Supplementary Table S28), because the 2025 hypertension guideline uses this threshold. Two extensions to other samples, specified in a protocol saved before they were run (extensions_protocol_20261010.md), are reported in Supplementary Tables S29 and S30. In the 2001–2002 sample, visit-1 inputs recomputed from the source files reproduced the Study 2 participant file exactly (cholesterol, eGFR, diabetes and UACR-model risk); visit-2 diabetes used the questionnaire status (diagnosis, insulin or pills) or the second-examination HbA1c ≥6.5%, and age, sex, blood pressure, smoking and treatment were held at visit 1. In NHANES 2021–2023, diabetes required observed HbA1c for a negative status, current smoking required 100 lifetime cigarettes and smoking every day or some days, antihypertensive treatment was coded 0 when the treatment question was skipped because hypertension had never been diagnosed, and inputs were clamped to the PREVENT domain as in Study 1. Population numbers are complete-case weighted totals scaled by the ratio of eligible to complete-case weights, which assumes that missing inputs are unrelated to risk. Blood analytes were weighted with the phlebotomy weight (WTPH2YR), which replaced the MEC weight named in the protocol. The transported intervals combine the curve bootstrap (population fixed) with the survey variance (curve fixed); intervals for proportions inside a zone reflect survey sampling only, because the zone limits are fixed at the Study 1 point estimates. Departures from the extensions protocol (the E1 variance, the E1 clamping, the E2 weights and scaling, and a factual correction about prescription data) are recorded in an addendum to that protocol and in the notes to Supplementary Tables S29 and S30. A second set (extensions2_protocol_20261010.md, saved before the decision analysis was computed; rough values of the other five analyses had been seen) is reported in Supplementary Tables S31 and S32: the antihypertensive drug-initiation recommendation of the 2025 AHA/ACC guideline at each visit; model-based disagreement with the usual-level category (the usual level being the average over the roughly 2-week two-visit process); clustering on the examining physician; the blood pressure minus lipid contribution; standardization with the change SD varying by age and race and ethnicity; and Study 2 disagreement after removing the average specimen ratio. Departures (the κ(r) display, an added smooth deconvolution, the deconvolution grid and convergence, the physician-clustered decision interval, the standardization seed and the reporting placements) are recorded in two addenda to that protocol. Separately, a coding error in the bootstrap interval for systematic visit effects was corrected as the protocol allows for coding errors (Supplementary Tables S1 and S11). The full hybrid tables (Supplementary Table S5) and distances in SD units were prespecified displays derived from the frozen participant export. None of these replaces a prespecified estimate.')
    h2('Software')
    env = R3['environment']
    p(f"Analyses used Python {env['python']} with NumPy {env['numpy']}, pandas {env['pandas']}, SciPy {env['scipy']}, pyreadstat {env['pyreadstat']} and rdata {env['rdata']}. The frozen protocol (SHA-256 {FRZ['protocol_sha256']}) is provided as a separate supplementary file; in it, Paper 1 denotes the urine-specimen analysis reported here as Study 2, then planned as a separate manuscript; its 5.34% and 4.25% (unrounded 4.247%) appear in the main text as 5.3% and 4.2%.")
    return b

