def build():
    from PIL import Image
    Image.open(ROOT / 'studies/uacr_prevent/figures_v3/figure_2.png').convert('RGB').save(OUT / 'figure_s3.png', dpi=(300, 300))
    Image.open(FIG / 'figure_7.png').convert('RGB').save(OUT / 'figure_s2.png', dpi=(300, 300))
    FIG7_LEGEND = [l for l in legends() if l.startswith('Figure 7.')][0].replace('Figure 7.', 'Figure S2.', 1)
    full = [('h1', 'Supplementary Results: full results text'), ('p', 'The main-text Results are a condensed version of the text below, which reports the results in full. Both are generated from the same result files, so every number is identical, except that the second post hoc set (Supplementary Tables S31 and S32) is reported only in the main text and those tables; figure and table numbers without the prefix S refer to the main text.')] + [(b[0], b[1].replace('Figure S2', 'Figure S3').replace('Figure 7 and', 'Supplementary Figure S2 and')) if b[0] == 'p' else b for b in results_detail()]
    blocks = [('title', 'Supplementary Material'), ('p', TITLE), ('p', 'Yunhao Jiang')] + methods() + methods2() + full + [('break',), ('h1', 'Supplementary Tables: Study 1 (NHANES III)')] + tables() + [('p', ''), ('h1', 'Supplementary Tables: Study 2 (NHANES 2009–2010 and 2001–2002)')] + tables2() + [('p', ''), ('h1', 'Supplementary Tables: post hoc additions')] + tables3() + [('break',), ('h1', 'Supplementary Figures'), ('figure', OUT / 'figure_s1.png', 'Figure S1. Sensitivity analyses. A, base PREVENT-ASCVD θ under each sensitivity analysis and alternative interval methods for the primary estimate (SA15); B, θ_U under the analyses run for the UACR model. Shaded band: ±1.5 pp around each primary estimate; for θ this is the prespecified abstract-reporting threshold for key analyses, and in B it is shown for reference only. Intervals are CR1 logit-t 95% CIs (SA10: cluster bootstrap with refitted weights).', 6.0), ('break',), ('figure', OUT / 'figure_s2.png', FIG7_LEGEND, 6.0), ('break',), ('figure', OUT / 'figure_s3.png', 'Figure S3. Study 2: where category changes occur (post hoc; NHANES 2009–2010, n = 3,166). a, UACR pairs on log axes colored by PREVENT-UACR category change with first-morning urine (unweighted points); dashed lines mark 30 mg/g and the shaded region holds pairs below 30 mg/g in both specimens. b, such pairs form 91.89% of the weighted cohort and 78.46% of its weighted category changes. c, three fixed first-specimen selection scenarios ("near risk boundary": within an inclusive 0.5 pp of 3%, 5% or 10%), with denominators of the whole cohort, all category changes and the selected participants; points are weighted percentages with 95% intervals, and 100% everyone-selected values are identities. d, fasting subset (n = 1,053; LDL cholesterol 70–189 mg/dL, no diabetes or statin use; fasting-subsample weights): left, downward and upward crossing frequencies with unweighted counts; right, paired net change in the fraction at or above each threshold (first-morning minus random) with 95% intervals. These describe risk-label changes, not prescribing changes or the benefit of retesting. Panel b shows percentages to two decimals as produced in the Study 2 analysis; panel c and the main text give one decimal (Supplementary Tables S21–S23).', 6.0)]
    order = W.number_citations(blocks)
    refs = [ref_text(k) for k in sorted(order, key=order.get)]
    doc = W.new_doc('Supplementary Material: ' + TITLE)
    for sec in doc.sections:
        sec.left_margin = sec.right_margin = W.Inches(0.7)
    doc.styles['Normal'].paragraph_format.line_spacing = 1.15
    W.render(doc, blocks, order, prefix='S')
    W.para(doc, 'Supplementary References', style='Heading 1')
    W.render(doc, [('refs', refs, 'S')], order)
    out = OUT / 'nh3_testretest_supplement.docx'
    doc.save(out)
    print('saved', out, 'refs', len(refs))
if __name__ == '__main__':
    build()
